// Service worker: makes the app work offline.
//
// On install, it stores every file in PRECACHE_URLS in a cache named after the app version
// and the build hash. It then answers requests for those files from the cache.
// A new version waits until the page asks it to take over (see js/pwa.js).
//
// Do not edit the PRECACHE block by hand. Run "bun run build" after each change to the app
// files; README.md, section "Build script", explains why. The build script copies APP_VERSION
// from js/version.js into the block. The service worker does not import js/version.js,
// because browsers can serve imported scripts from their HTTP cache.

// BEGIN PRECACHE (generated by scripts/build.js, do not edit)
const APP_VERSION = '1.44.20261010';
const BUILD_HASH = '3f9a30a14728';
const PRECACHE_URLS = [
  'css/flashcards.css',
  'css/img-to-md.css',
  'css/pwa.css',
  'flashcards.html',
  'img-to-md.html',
  'img/icon.svg',
  'img/icons.svg',
  'img/icons/apple-touch-icon.png',
  'img/icons/icon-192.png',
  'img/icons/icon-512.png',
  'img/watermark.svg',
  'js/flashcards.js',
  'js/img-to-md.js',
  'js/pwa.js',
  'js/version.js',
  'manifest.webmanifest',
  'vendor/dompurify/purify.min.js',
  'vendor/fonts/dm-sans-latin-300-normal.woff2',
  'vendor/fonts/dm-sans-latin-400-normal.woff2',
  'vendor/fonts/dm-sans-latin-500-normal.woff2',
  'vendor/fonts/dm-sans-latin-ext-300-normal.woff2',
  'vendor/fonts/dm-sans-latin-ext-400-normal.woff2',
  'vendor/fonts/dm-sans-latin-ext-500-normal.woff2',
  'vendor/fonts/fonts.css',
  'vendor/fonts/lora-latin-400-italic.woff2',
  'vendor/fonts/lora-latin-400-normal.woff2',
  'vendor/fonts/lora-latin-600-normal.woff2',
  'vendor/fonts/lora-latin-ext-400-italic.woff2',
  'vendor/fonts/lora-latin-ext-400-normal.woff2',
  'vendor/fonts/lora-latin-ext-600-normal.woff2',
  'vendor/katex/contrib/auto-render.min.js',
  'vendor/katex/fonts/KaTeX_AMS-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Caligraphic-Bold.woff2',
  'vendor/katex/fonts/KaTeX_Caligraphic-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Fraktur-Bold.woff2',
  'vendor/katex/fonts/KaTeX_Fraktur-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Main-Bold.woff2',
  'vendor/katex/fonts/KaTeX_Main-BoldItalic.woff2',
  'vendor/katex/fonts/KaTeX_Main-Italic.woff2',
  'vendor/katex/fonts/KaTeX_Main-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Math-BoldItalic.woff2',
  'vendor/katex/fonts/KaTeX_Math-Italic.woff2',
  'vendor/katex/fonts/KaTeX_SansSerif-Bold.woff2',
  'vendor/katex/fonts/KaTeX_SansSerif-Italic.woff2',
  'vendor/katex/fonts/KaTeX_SansSerif-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Script-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Size1-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Size2-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Size3-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Size4-Regular.woff2',
  'vendor/katex/fonts/KaTeX_Typewriter-Regular.woff2',
  'vendor/katex/katex.min.css',
  'vendor/katex/katex.min.js',
  'vendor/marked/marked.umd.js',
];
// END PRECACHE

const CACHE_PREFIX = 'flashcards-';
const CACHE_NAME   = `${CACHE_PREFIX}${APP_VERSION}-${BUILD_HASH}`;

self.addEventListener('install', event => {
  // cache: 'reload' skips the browser's HTTP cache, so a new version never stores stale files
  const requests = PRECACHE_URLS.map(url => new Request(url, { cache: 'reload' }));
  event.waitUntil(caches.open(CACHE_NAME).then(cache => cache.addAll(requests)));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(
      names.filter(n => n.startsWith(CACHE_PREFIX) && n !== CACHE_NAME).map(n => caches.delete(n))
    );
    await self.clients.claim();
  })());
});

// The page sends this after the user clicks "Reload" in the update banner.
self.addEventListener('message', event => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET' || new URL(request.url).origin !== self.location.origin) return;

  event.respondWith((async () => {
    const cache  = await caches.open(CACHE_NAME);
    const cached = await cache.match(request, { ignoreSearch: true });
    if (cached) return cached;
    try {
      return await fetch(request);
    } catch (err) {
      // Offline and not in the cache: send page navigations to the app, fail other requests.
      // A redirect (not the page itself) keeps the relative links of the page working.
      if (request.mode === 'navigate') {
        return Response.redirect(new URL('flashcards.html', self.registration.scope).href, 302);
      }
      throw err;
    }
  })());
});
